<?php $admin_title='Stock Control';include '_header.php';$products=$pdo->query("SELECT id,name,quantity,unit FROM products WHERE status='active' ORDER BY name")->fetchAll();$ins=stock_history($pdo,"type='IN'",[],40);$outs=stock_history($pdo,"type='OUT'",[],40);function movementForm($type,$products){?><form class="ajax-form stock-form" action="api/stock_move.php" method="post" data-reload="1"><input type="hidden" name="csrf" value="<?=token()?>"><input type="hidden" name="type" value="<?=$type?>"><div class="form-group"><label>Product</label><select class="form-control" name="product_id" data-required data-message="Select a product."><option value="">Select product</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?> — <?=$p['quantity'].' '.e($p['unit'])?></option><?php endforeach;?></select></div><div class="form-grid"><div class="form-group"><label>Quantity</label><input class="form-control" type="number" min="1" name="quantity" data-required data-message="Enter a quantity greater than zero."></div><div class="form-group"><label>Reference</label><input class="form-control" name="reference_no" placeholder="<?=$type==='IN'?'GRN-1001':'SO-1001'?>"></div></div><div class="form-group"><label>Reason</label><input class="form-control" name="reason" data-required data-message="Enter the reason for this movement." placeholder="<?=$type==='IN'?'Supplier delivery / Return':'Sale / Damage / Transfer'?>"></div><button class="btn <?=$type==='IN'?'btn-success':'btn-warning'?>" type="submit"><i class="fa-solid <?=$type==='IN'?'fa-arrow-down':'fa-arrow-up'?>"></i> Save Stock <?=$type==='IN'?'In':'Out'?></button></form><?php }?><div class="stock-control-grid"><section class="stock-panel stock-in-panel"><div class="stock-panel-head"><span class="stock-icon"><i class="fa-solid fa-arrow-down"></i></span><div><span class="kicker">RECEIVING</span><h2>Stock In</h2><p>Add deliveries, returns and new inventory.</p></div></div><?php movementForm('IN',$products);?></section><section class="stock-panel stock-out-panel"><div class="stock-panel-head"><span class="stock-icon"><i class="fa-solid fa-arrow-up"></i></span><div><span class="kicker">ISSUING</span><h2>Stock Out</h2><p>Record sales, damage, transfers and other issues.</p></div></div><?php movementForm('OUT',$products);?></section></div><div class="movement-columns"><div class="panel"><div class="panel-head"><h2><i class="fa-solid fa-arrow-down movement-in"></i> Recent Stock In</h2></div><?php foreach($ins as $h):?><div class="movement-row"><div><b><?=e($h['product_name'])?></b><small><?=date('d M Y H:i',strtotime($h['created_at']))?> · <?=e($h['reason'])?></small></div><strong class="movement-in">+<?=$h['quantity']?></strong></div><?php endforeach;?></div><div class="panel"><div class="panel-head"><h2><i class="fa-solid fa-arrow-up movement-out"></i> Recent Stock Out</h2></div><?php foreach($outs as $h):?><div class="movement-row"><div><b><?=e($h['product_name'])?></b><small><?=date('d M Y H:i',strtotime($h['created_at']))?> · <?=e($h['reason'])?></small></div><strong class="movement-out">-<?=$h['quantity']?></strong></div><?php endforeach;?></div></div><?php include '_footer.php'; ?>